 ```python
# Import necessary modules
from pychrono.core import *
from pychrono.fea import *
from pychrono.irrlicht import *
from pychrono.system import *
from pychrono.vehicle import *

# Initialize the PyChrono environment and core components
myChrono = Chrono::CreateSystem()
myFea = FEAEngineManager(myChrono);
myIrrlicht = IrrlichtEngine(myChrono, "Jeffcott Rotor IGA", 800, 600,
                            IRR_WINDOW_MAXIMIZED);
myIrrlicht.AddLogo(pathicon+"logo_small.png");
myIrrlicht.SetShowLogo(true);
myIrrlicht.SetShowFPS(true);
myIrrlicht.SetShowCollisionShapes(true);
myIrrlicht.SetShowBoundingBoxes(false);
myIrrlicht.SetShowText(true);
myIrrlicht.SetShowGrid(false);
myIrrlicht.SetChaseCamera(true, true);

# Create ground body
ground = RigidBody(myChrono, "ground");
ground_shape = BoxShape(Vector3(100, 1, 100));
ground_transform = Transform(Vector3(0, -1, 0));
ground.AddShape(ground_shape, ground_transform);
myChrono.AddBody(ground);

# Create IGA beam
beam_width = 0.1;
beam_height = 0.1;
beam_length = 1;
beam_fea = IGA_Beam(myChrono, "beam", beam_width, beam_height, beam_length);
beam_fea.SetDensity(7850);
beam_fea.SetColor(ChVector3(0.5, 0.5, 0.5));
myFea.AddElement(beam_fea);

# Create flywheel
flywheel_radius = 0.2;
flywheel_thickness = 0.05;
flywheel_mass = 2;
flywheel_fea = IGA_Disk(myChrono, "flywheel", flywheel_radius, flywheel_thickness);
flywheel_fea.SetDensity(flywheel_mass / (pi * flywheel_radius * flywheel_radius));
flywheel_fea.SetColor(ChVector3(0.5, 0.5, 0.5));
myFea.AddElement(flywheel_fea);
beam_fea.AddChild(flywheel_fea, ChCoordsys(ChVector(0, 0, 0)));

# Create rotational motor
motor = RotationalMotor(myChrono, "motor");
motor.SetBody1(beam_fea);
motor.SetBody2(ground);
motor.SetPoint1(ChVector(0, 0, 0));
motor.SetPoint2(ChVector(0, -1, 0));
motor.SetAngularSpeed(20 * CH_C_PI);
myChrono.AddForce(motor);

# Set up visualization
myIrrlicht.AddTypicalSkyBox();
myIrrlicht.AddCamera(ChVector(beam_length, 0.5, beam_length), ChVector(0, 0.5, 0));
myIrrlicht.AddLight(ChVector(beam_length, 5, beam_length), ChVector(3, 3, 3), 500);
myIrrlicht.AddFEAElement(beam_fea, ChVector(0, 0, 0), ChColor(0.5, 0.5, 0.5));
myIrrlicht.AddFEADisk(flywheel_fea, ChVector(0, 0, 0), ChColor(0.5, 0.5, 0.5));
myIrrlicht.AddRigidBody(ground, ChVector(0, -1, 0), ChColor(0.5, 0.5, 0.5));

# Set simulation parameters
myChrono.SetStepSize(1e-4);
myChrono.Set_G_acc(Vector3(0, -9.81, 0));
myChrono.Set_W(1 / 500);

# Run the simulation
sim_time = 5;
for i in range(int(sim_time / myChrono.Get_W())):
    myChrono.DoStepDynamics();
    myIrrlicht.DrawAll();

myIrrlicht.WaitKey(0);
myIrrlicht.Close();
```

This script creates a Jeffcott rotor simulation using PyChrono and IGA beams. The rotor consists of a beam and a flywheel at its center. A rotational motor is attached to the beam, driving one end of the beam. The visualization includes FEM visualization and an Irrlicht window to observe the dynamics of the beam and flywheel system.
